        int len = msg.size();

        if (op == "rotate") {
            // Forward: rotate left by val. Inverse: rotate right by val
            val = ((val % len) + len) % len;
            // rotate right by val = rotate left by (len - val)
            int inv = (len - val) % len;
            msg = msg.substr(inv) + msg.substr(0, inv);
        } else if (op == "swap") {
            int half = len / 2;
            msg = msg.substr(half) + msg.substr(0, half);
        } else if (op == "reverse") {
            reverse(msg.begin(), msg.end());
        } else if (op == "increment") {
            for (char& c : msg) {
