    // in reverse order.
    for (int i = m - 1; i >= 0; --i) {
        int op = ops[i];

        if (op == 1) {
            // Forward: rotate right by 1
            // Inverse: rotate left by 1
            if (n > 1) rotate(s.begin(), s.begin() + 1, s.end());
        } else if (op == 2) {
            // Swap halves; self-inverse
            int half = n / 2;
            s = s.substr(half) + s.substr(0, half);
        } else if (op == 3) {
            // Reverse; self-inverse
            reverse(s.begin(), s.end());
        } else if (op == 4) {
            // Forward: each digit +1 mod 10
            // Inverse: each digit -1 mod 10
            for (char &c : s) {
                if (isdigit(c)) c = char('0' + (c - '0' + 9) % 10);
            }
        } else if (op == 5) {
            // Forward: each digit -1 mod 10
            // Inverse: each digit +1 mod 10
            for (char &c : s) {
                if (isdigit(c)) c = char('0' + (c - '0' + 1) % 10);
            }
        }
    }

    cout << s << '\n';
    return 0;
