void rotate_left(char *s, int n) {
    int len = strlen(s);
    n %= len;
    if (n == 0) return;
    char *temp = malloc(len + 1);
    strcpy(temp, s + n);
    strncat(temp, s, n);
    strcpy(s, temp);
    free(temp);
}

void rotate_right(char *s, int n) {
    int len = strlen(s);
    n %= len;
    if (n == 0) return;
    rotate_left(s, len - n);
}

void swap_halves(char *s) {
    int len = strlen(s);
    int mid = len / 2;
    char *temp = malloc(len + 1);
    strcpy(temp, s + mid);
    strncat(temp, s, mid);
    strcpy(s, temp);
    free(temp);
}

void reverse(char *s) {
    int len = strlen(s);
    for (int i = 0; i < len / 2; i++) {
        char t = s[i];
        s[i] = s[len - 1 - i];
        s[len - 1 - i] = t;
    }
}

void increment(char *s) {
    for (int i = 0; s[i]; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            s[i] = (s[i] == '9') ? '0' : s[i] + 1;
        }
    }
}

void decrement(char *s) {
    for (int i = 0; s[i]; i++) {
        if (s[i] >= '0' && s[i] <= '9') {
            s[i] = (s[i] == '0') ? '9' : s[i] - 1;
        }
    }
}

