void rotate_left(char *s, int n) {
    char tmp = s[0];
    for(int i = 0; i < n-1; i++) s[i] = s[i+1];
    s[n-1] = tmp;
}

void rotate_right(char *s, int n) {
    char tmp = s[n-1];
    for(int i = n-1; i > 0; i--) s[i] = s[i-1];
    s[0] = tmp;
}

void swap_halves(char *s, int n) {
    int half = n/2;
    char tmp[1001];
    strncpy(tmp, s+half, n-half);
    strncpy(tmp+(n-half), s, half);
    tmp[n] = '\0';
    strcpy(s, tmp);
}

void reverse_str(char *s, int n) {
    for(int i = 0; i < n/2; i++) {
        char t = s[i]; s[i] = s[n-1-i]; s[n-1-i] = t;
    }
}

void inc_digits(char *s, int n) {
    for(int i = 0; i < n; i++)
        if(s[i] >= '0' && s[i] <= '9')
            s[i] = '0' + (s[i]-'0'+1)%10;
}

void dec_digits(char *s, int n) {
