static void rotate_left(char *a, int n, int k) {
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    if (k == 0) return;
    memcpy(tmp, a + k, n - k);
    memcpy(tmp + (n - k), a, k);
    memcpy(a, tmp, n);
    a[n] = '\0';
}

static void swap_halves(char *a, int n) {
    int mid = n / 2;
    if (n % 2 == 0) {
        memcpy(tmp, a + mid, mid);
        memcpy(tmp + mid, a, mid);
    } else {
        /* keep middle character in place:
           abcde -> decab? No statement details available.
           Common interpretation: swap left and right halves around middle:
           ab[c]de -> de[c]ab
        */
        memcpy(tmp, a + mid + 1, n - mid - 1);
        tmp[n - mid - 1] = a[mid];
        memcpy(tmp + (n - mid), a, mid);
    }
    memcpy(a, tmp, n);
    a[n] = '\0';
}

static void reverse_str(char *a, int n) {
    for (int i = 0, j = n - 1; i < j; i++, j--) {
        char c = a[i];
        a[i] = a[j];
        a[j] = c;
    }
}

