public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read final message
        String finalMessage = br.readLine().trim();

        // Read number of messengers
        int n = Integer.parseInt(br.readLine().trim());

        // Read messenger operations
        String[] operations = new String[n];
        for (int i = 0; i < n; i++) {
            operations[i] = br.readLine().trim();
        }

        // Apply operations in reverse order
        String current = finalMessage;
        for (int i = n - 1; i >= 0; i--) {
            current = reverseOperation(current, operations[i]);
        }

        // Output original message
        System.out.println(current);
    }

    private static String reverseOperation(String s, String op) {
        if (op.startsWith("ROT")) {
            int k = Integer.parseInt(op.substring(3));
            // Reverse of ROT k is ROT (len - k % len)
            int len = s.length();
            int shift = (len - (k % len)) % len;
            return s.substring(shift) + s.substring(0, shift);
        } else if (op.startsWith("SWAP")) {
            // Reverse of SWAP: swap halves again
            int len = s.length();
            int mid = len / 2;
            if (len % 2 == 0) {
                return s.substring(mid) + s.substring(0, mid);
            } else {
                // odd length: first half has mid+1, second half has mid
                return s.substring(mid + 1) + s.charAt(mid) + s.substring(0, mid);
            }
        } else if (op.equals("REV")) {
            // Reverse of REV is REV itself
            return new StringBuilder(s).reverse().toString();
        } else if (op.startsWith("INC")) {
            // Reverse of INC is DEC
            int k = Integer.parseInt(op.substring(3));
            StringBuilder sb = new StringBuilder();
            for (char c : s.toCharArray()) {
                if (Character.isDigit(c)) {
                    int digit = (c - '0' - k + 10) % 10;
                    sb.append((char) ('0' + digit));
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        } else if (op.startsWith("DEC")) {
            // Reverse of DEC is INC
            int k = Integer.parseInt(op.substring(3));
            StringBuilder sb = new StringBuilder();
            for (char c : s.toCharArray()) {
                if (Character.isDigit(c)) {
                    int digit = (c - '0' + k) % 10;
                    sb.append((char) ('0' + digit));
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }
        // Should not reach here
        return s;
    }
}

