public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String finalMessage = br.readLine();
        String messengers = br.readLine();

        if (finalMessage == null) finalMessage = "";
        if (messengers == null) messengers = "";

        String msg = finalMessage;

        // To recover the original message, apply inverse operations
        // in reverse order of the messengers.
        for (int i = messengers.length() - 1; i >= 0; i--) {
            char c = messengers.charAt(i);
            switch (c) {
                case 'R':
                    msg = rotateRight(msg); // inverse of left rotation
                    break;
                case 'L':
                    msg = rotateLeft(msg);  // inverse of right rotation
                    break;
                case 'S':
                    msg = swapHalves(msg);  // self-inverse
                    break;
                case 'V':
                    msg = reverse(msg);     // self-inverse
                    break;
                case 'I':
                    msg = decrementDigits(msg); // inverse of increment
                    break;
                case 'D':
                    msg = incrementDigits(msg); // inverse of decrement
                    break;
            }
        }

        System.out.println(msg);
    }

    // Left rotation by 1
    private static String rotateLeft(String s) {
        int n = s.length();
        if (n <= 1) return s;
        return s.substring(1) + s.charAt(0);
    }

    // Right rotation by 1
    private static String rotateRight(String s) {
        int n = s.length();
        if (n <= 1) return s;
        return s.charAt(n - 1) + s.substring(0, n - 1);
    }

    // Swap first and second halves
    // For odd length, middle character stays in place.
    private static String swapHalves(String s) {
        int n = s.length();
        int mid = n / 2;
        if (n % 2 == 0) {
            return s.substring(mid) + s.substring(0, mid);
        } else {
            return s.substring(mid + 1) + s.charAt(mid) + s.substring(0, mid);
        }
    }

    private static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    // Increment every digit modulo 10
    private static String incrementDigits(String s) {
        char[] a = s.toCharArray();
        for (int i = 0; i < a.length; i++) {
            if (a[i] >= '0' && a[i] <= '9') {
                a[i] = (char) ('0' + (a[i] - '0' + 1) % 10);
            }
        }
        return new String(a);
    }

    // Decrement every digit modulo 10
    private static String decrementDigits(String s) {
        char[] a = s.toCharArray();
        for (int i = 0; i < a.length; i++) {
            if (a[i] >= '0' && a[i] <= '9') {
                a[i] = (char) ('0' + (a[i] - '0' + 9) % 10);
            }
        }
        return new String(a);
    }
}

import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    operations = []
    for i in range(1, n + 1):
        parts = data[i].strip().split()
        op = parts[0]
        if op in ("INCREMENT", "DECREMENT"):
            operations.append((op, None))
        else:
            k = int(parts[1])
            operations.append((op, k))

    final_message = data[n + 1].strip()
    msg = list(final_message)
    m = len(msg)

    # Apply operations in reverse order
    for op, k in reversed(operations):
        if op == "ROTATE":
            # reverse of rotate left by k is rotate right by k
            k = k % m
            msg = msg[-k:] + msg[:-k]
        elif op == "SWAP":
            # swap halves back: same operation reverses itself if length even
            mid = k % m
            msg = msg[mid:] + msg[:mid]
        elif op == "REVERSE":
            msg.reverse()
        elif op == "INCREMENT":
            for i in range(m):
                if msg[i].isdigit():
                    d = int(msg[i])
                    d = (d - 1) % 10
                    msg[i] = str(d)
        elif op == "DECREMENT":
            for i in range(m):
                if msg[i].isdigit():
                    d = int(msg[i])
                    d = (d + 1) % 10
                    msg[i] = str(d)

    sys.stdout.write("".join(msg))

