import sys

def inv_rotate_left(s):
    # Messenger rotated left by one => inverse is rotate right by one
    if len(s) <= 1:
        return s
    return s[-1] + s[:-1]

def inv_rotate_right(s):
    # Messenger rotated right by one => inverse is rotate left by one
    if len(s) <= 1:
        return s
    return s[1:] + s[0]

def swap_halves(s):
    # Self-inverse
    n = len(s)
    h = n // 2
    return s[h:] + s[:h]

def reverse_str(s):
    return s[::-1]

def dec_digits(s):
    # Inverse of increment digits
    res = []
    for ch in s:
        if '0' <= ch <= '9':
            res.append(chr((ord(ch) - ord('0') - 1) % 10 + ord('0')))
        else:
            res.append(ch)
    return ''.join(res)

def inc_digits(s):
    # Inverse of decrement digits
    res = []
    for ch in s:
        if '0' <= ch <= '9':
            res.append(chr((ord(ch) - ord('0') + 1) % 10 + ord('0')))
        else:
            res.append(ch)
    return ''.join(res)

def apply_inverse(msg, op):
    c = op.lower()
    # Support common messenger operation notations
    if c in ('l', 'left', 'rotateleft', 'rotate-left'):
        return inv_rotate_left(msg)
    if c in ('r', 'right', 'rotateright', 'rotate-right'):
        return inv_rotate_right(msg)
    if c in ('s', 'swap', 'swaphalves', 'swap-halves'):
        return swap_halves(msg)
    if c in ('v', 'rev', 'reverse'):
        return reverse_str(msg)
    if c in ('i', 'inc', 'increment', '+'):
        return dec_digits(msg)
    if c in ('d', 'dec', 'decrement', '-'):
        return inc_digits(msg)
    return msg

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Assumed input format:
    # final_message
    # n
    # n messenger operation tokens
    #
    # or:
    # n
    # final_message
    # n tokens
    #
    # We support both common variants.

    if data[0].isdigit():
        n = int(data[0])
        final_msg = data[1]
        ops = data[2:2+n]
    else:
        final_msg = data[0]
        n = int(data[1])
        ops = data[2:2+n]

    msg = final_msg
    for op in reversed(ops):
        msg = apply_inverse(msg, op)

    sys.stdout.write(msg)

if __name__ == "__main__":
    main()
